-- AF_RecipeVendor[item] = vendor price per unit (copper) for reagents sold by vendors.
-- AF_NoSell[item] = "tool" (a profession tool, fishing pole, hearthstone...) or "conjured": AF Sell never lists it.
-- AF_CrateFills[crate] = { item, count, item, count, ... }: any one bundle fills that Waylaid Crate.
-- AF_Gear[item] = (((class*32 + subclass)*32 + slot)*8 + quality)*1024 + item level: tradable weapons (class 0)
--   and armor (class 1); slot = InventoryType, robes counted as chest. For estimating gear with no market data.
